BEGIN;CREATE TABLE public.accounting_close_partials(kind text NOT NULL,value jsonb NOT NULL,CONSTRAINT accounting_close_partials_kind_check CHECK ((kind = ANY (ARRAY['earned_plan_window'::text, 'round2_union_window'::text, 'round2_club_window'::text, 'round3_union_window'::text, 'round3_club_window'::text, 'round3_union_plan'::text, 'round3_club_plan'::text, 'pnl_flows_window'::text, 'pnl_hands_window'::text]))));
INSERT INTO public.accounting_close_partials SELECT kind,jsonb_build_object('unchanged',kind)FROM unnest(ARRAY['earned_plan_window','round2_union_window','round2_club_window','round3_union_window','round3_club_window','round3_union_plan','round3_club_plan','pnl_flows_window','pnl_hands_window'])kind;CREATE TEMP TABLE original9 AS TABLE public.accounting_close_partials;
ALTER TABLE public.accounting_close_partials DROP CONSTRAINT accounting_close_partials_kind_check;ALTER TABLE public.accounting_close_partials ADD CONSTRAINT accounting_close_partials_kind_check CHECK ((kind = ANY (ARRAY['earned_plan_window'::text, 'round2_union_window'::text, 'round2_club_window'::text, 'round3_union_window'::text, 'round3_club_window'::text, 'round3_union_plan'::text, 'round3_club_plan'::text, 'pnl_flows_window'::text, 'pnl_hands_window'::text, 'pnl_linked_window'::text])));
INSERT INTO public.accounting_close_partials VALUES('pnl_linked_window','{}');
DO $$BEGIN IF EXISTS((SELECT*FROM public.accounting_close_partials WHERE kind<>'pnl_linked_window'EXCEPT ALL TABLE original9)UNION ALL(TABLE original9 EXCEPT ALL SELECT*FROM public.accounting_close_partials WHERE kind<>'pnl_linked_window'))THEN RAISE EXCEPTION 'existing_kind_rows_changed';END IF;BEGIN INSERT INTO public.accounting_close_partials VALUES('unknown_kind','{}');RAISE EXCEPTION 'unknown_kind_accepted';EXCEPTION WHEN check_violation THEN NULL;END;RAISE NOTICE 'KIND_EXTENSION_PASS:old9_exact,newkind_admitted,unknown_refused';END;$$;ROLLBACK;
